import React, { useEffect, useState } from "react";
import "./App.css";
import ResponsiveNavbar from "./components/ResponsiveNavbar";
import VideoModal from "./components/VideoModal";
import ScrollToTop from "./components/ScrollToTop";
import MasonryGallery from "./components/MasonryGallery";
import HeroArea from "./components/HeroArea";
import LatestAlbums from "./components/LatestAlbums";
import BuyNowArea from "./components/BuyNowArea";
import FeaturedArtist from "./components/FeaturedArtist";
import ContactArea from "./components/ContactArea";
import AppFooter from "./components/AppFooter";
import { Carousel, Row, Col, Container, Button } from "react-bootstrap";

const albums = [
  { img: "img/bg-img/a1.jpg", title: "The Cure", subtitle: "Second Song" },
  { img: "img/bg-img/a2.jpg", title: "Sam Smith", subtitle: "Underground" },
  { img: "img/bg-img/a3.jpg", title: "Will I am", subtitle: "First" },
  { img: "img/bg-img/a4.jpg", title: "The Cure", subtitle: "Second Song" },
  { img: "img/bg-img/a5.jpg", title: "DJ SMITH", subtitle: "The Album" },
  { img: "img/bg-img/a6.jpg", title: "The Ustopable", subtitle: "Unplugged" },
  { img: "img/bg-img/a7.jpg", title: "Beyonce", subtitle: "Songs" },
];

const buyItems = [
  {
    img: "img/bg-img/b1.jpg",
    title: "Garage Band",
    subtitle: "Radio Station",
    price: "$0.90",
    category: "vinyl",
  },
  {
    img: "img/bg-img/b2.jpg",
    title: "Noises",
    subtitle: "Buble Gum",
    price: "$0.90",
    category: "mp3",
  },
  {
    img: "img/bg-img/b3.jpg",
    title: "Jess Parker",
    subtitle: "The Album",
    price: "$0.90",
    category: "vinyl",
  },
  {
    img: "img/bg-img/b4.jpg",
    title: "Noises",
    subtitle: "Buble Gum",
    price: "$0.90",
    category: "merch",
  },
  {
    img: "img/bg-img/b1.jpg",
    title: "Garage Band",
    subtitle: "Radio Station",
    price: "$0.90",
    category: "mp3",
  },
  {
    img: "img/bg-img/b2.jpg",
    title: "Noises",
    subtitle: "Buble Gum",
    price: "$0.90",
    category: "merch",
  },
  {
    img: "img/bg-img/b3.jpg",
    title: "Jess Parker",
    subtitle: "The Album",
    price: "$0.90",
    category: "vinyl",
  },
  {
    img: "img/bg-img/b4.jpg",
    title: "Noises",
    subtitle: "Buble Gum",
    price: "$0.90",
    category: "mp3",
  },
];

function chunkArray(arr, size) {
  const chunks = [];
  for (let i = 0; i < arr.length; i += size)
    chunks.push(arr.slice(i, i + size));
  return chunks;
}

export default function App() {
  const [videoSrc, setVideoSrc] = useState(null);
  const [videoOpen, setVideoOpen] = useState(false);

  useEffect(() => {
    // remove preloader if present
    const p = document.querySelector(".preloader");
    if (p) {
      p.style.transition = "opacity 300ms ease";
      p.style.opacity = "0";
      setTimeout(() => p.remove(), 350);
    }
  }, []);

  return (
    <div className="App">
      <ResponsiveNavbar />

      <HeroArea
        onWatchVideo={(src) => {
          setVideoSrc(src);
          setVideoOpen(true);
        }}
      />

      <LatestAlbums albumList={albums} />

      <BuyNowArea items={buyItems} />

      <FeaturedArtist />

      <ContactArea />

      <AppFooter />

      <VideoModal show={videoOpen} onHide={() => setVideoOpen(false)} src={videoSrc} />
      <ScrollToTop />
    </div>
  );
}
